#!/usr/bin/env bash
set -euo pipefail; SCRIPT="${1:-}"; shift || true; [[ -z "$SCRIPT" ]] && echo "Usage: $0 <trial_script.py> [trial args...]  (env: KEEP_LAST=2 CLEANUP_CAMERA=1 FORCE_KILL=0 RESTART_ARGUS=0 BASE_DIR=~/Desktop/demo_artifacts)" && exit 2; BASE_DIR="${BASE_DIR:-$HOME/Desktop/demo_artifacts}"; KEEP_LAST="${KEEP_LAST:-2}"; CLEANUP_CAMERA="${CLEANUP_CAMERA:-1}"; FORCE_KILL="${FORCE_KILL:-0}"; RESTART_ARGUS="${RESTART_ARGUS:-0}"; SPACE_MGR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/space_management.py"; python3 "$SCRIPT" "$@" || true; ARGS=(--base-dir "$BASE_DIR" --keep-last "$KEEP_LAST"); [[ "$CLEANUP_CAMERA" == "1" ]] && ARGS+=(--cleanup-camera); [[ "$FORCE_KILL" == "1" ]] && ARGS+=(--force-kill-camera-users); [[ "$RESTART_ARGUS" == "1" ]] && ARGS+=(--restart-nvargus-daemon); python3 "$SPACE_MGR" "${ARGS[@]}"